// Ganho: move a coluna só se STAGE_GANHO estiver preenchido no Config Ganho.
// Vazio = só comenta na timeline. É de propósito: mover pra coluna errada é
// pior do que não mover, e ninguém decidiu ainda qual é a coluna de ganho.
const cfg = $('Config Ganho').first().json;
const b = $('Webhook Ganho (qs-ganho)').first().json.body || {};

if (!b.bitrix_id) return [];

const valor = b.closed_value;
const temValor = valor !== null && valor !== undefined && valor !== '' && Number(valor) > 0;

const fields = {};
if (cfg.STAGE_GANHO) fields.STAGE_ID = String(cfg.STAGE_GANHO);
// OPPORTUNITY é o campo nativo de valor do negócio no Bitrix.
if (temValor) fields.OPPORTUNITY = Number(valor);

return [{ json: {
  id: Number(b.bitrix_id),
  mexe_no_card: Object.keys(fields).length > 0,
  fields,
  comentario: '🏆 Lead marcado como GANHO no QS.' +
    (temValor ? '\nValor fechado: R$ ' + Number(valor).toLocaleString('pt-BR') : '\nValor fechado: não informado') +
    (b.full_name ? '\nLead: ' + b.full_name : '')
} }];

// AQUI mora o "primeiro contato": não existe contador nem flag — a regra é
// "só move quem AINDA está em Novo lead". Da 2ª atividade em diante o negócio já
// saiu dessa coluna, então o evento chega, olha e não faz nada. De quebra, isso
// impede o robô de puxar PRA TRÁS um negócio que já avançou (Reunião, Ganho,
// Perdido) e torna o disparo idempotente: repetir não estraga nada.
const cfg = $('Config 1o contato').first().json;
const evt = $('Webhook 1o contato (qs-primeiro-contato)').first().json.body || {};
const resp = $input.first().json;

// O crm.deal.get acima segue em frente mesmo com erro (onError). Se o Bitrix
// RECUSOU, isso tem que ficar VERMELHO: sem este throw o único sintoma é "o
// negócio não anda" e a execução aparece verde. Erro clássico:
// insufficient_scope = o webhook de ENTRADA foi criado sem a permissão CRM.
if (resp && resp.error) {
  throw new Error('Bitrix recusou o crm.deal.get: ' + resp.error + ' — ' + (resp.error_description || ''));
}

const r = resp.result;
if (!r) return [];   // negócio não encontrado no Bitrix

// Opcional: mover só quando o SDR REALMENTE falou com a pessoa.
if (String(cfg.SO_ALCANCOU || '').toLowerCase() === 'sim' && evt.alcancou !== true) return [];

if (String(r.STAGE_ID || '') !== String(cfg.STAGE_DE)) return [];

return [{ json: {
  id: String(r.ID),
  de: String(r.STAGE_ID || ''),
  para: String(cfg.STAGE_PARA),
  canal: String(evt.canal || ''),
  desfecho: String(evt.desfecho || ''),
  sdr: String(evt.sdr || '')
} }];

const body = $('Webhook Reunião (qs-reuniao)').first().json.body || {};
const cfg = $('Config Reuniao').first().json;

const mapa = {};
for (const it of $('Buscar de-para').all()) {
  const r = it.json;
  if (r && r.alias && r.field_name) mapa[r.alias] = r.field_name;
}

const opcoes = {};
for (const it of $('Buscar opções').all()) {
  const r = it.json;
  if (!r || !r.alias) continue;
  (opcoes[r.alias] = opcoes[r.alias] || []).push({ id: Number(r.option_id), value: String(r.value == null ? '' : r.value) });
}

const normalizar = (s) => String(s == null ? '' : s)
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .toLowerCase().replace(/\s+/g, ' ').trim();

// Casa o nome do QS com o rótulo da opção no Bitrix. Tenta o nome inteiro e,
// se não bater, o primeiro nome — o Bitrix costuma ter só "Talita" enquanto o
// QS tem "Talita Carvalho".
// Casa o nome que veio do QS com o rotulo da opcao no Bitrix.
//
// Nao da pra casar so pelo primeiro nome: a lista 'Quem fez o agendamento?'
// tem 'Victor Hugo - SDR' E 'Victor Maldonado - Closer'. Por primeiro nome, o
// agendamento do Victor Hugo poderia ser creditado ao Victor Maldonado.
// Por isso o primeiro nome so vale quando ha UM candidato unico.
function acharOpcao(alias, nome) {
  const lista = opcoes[alias] || [];
  const alvo = normalizar(nome);
  if (!alvo || !lista.length) return null;

  // 1) igual
  let hit = lista.find(function (o) { return normalizar(o.value) === alvo; });
  if (hit) return hit.id;

  // 2) o rotulo comeca com o nome do QS ('Talita Carvalho' -> 'Talita Carvalho - Closer')
  hit = lista.find(function (o) { return normalizar(o.value).indexOf(alvo + ' ') === 0; });
  if (hit) return hit.id;

  // 3) o nome do QS comeca com o rotulo ('Yanca Manuella Ruivo' -> 'Yanca Manuella')
  hit = lista.find(function (o) {
    const v = normalizar(o.value);
    return v.length > 3 && alvo.indexOf(v + ' ') === 0;
  });
  if (hit) return hit.id;

  // 4) todas as palavras do nome do QS aparecem no rotulo
  const partes = alvo.split(' ').filter(function (x) { return x.length > 2; });
  if (partes.length > 1) {
    const todos = lista.filter(function (o) {
      const v = normalizar(o.value);
      return partes.every(function (x) { return v.indexOf(x) >= 0; });
    });
    if (todos.length === 1) return todos[0].id;
  }

  // 5) primeiro nome — SO se for unico, senao e melhor nao preencher do que
  //    creditar a pessoa errada (o comentario na timeline avisa o que faltou).
  const primeiro = alvo.split(' ')[0];
  const candidatos = lista.filter(function (o) { return normalizar(o.value).split(' ')[0] === primeiro; });
  return candidatos.length === 1 ? candidatos[0].id : null;
}


// O QS grava em UTC. Mandar assim faz a reunião aparecer 3h adiantada no card.
// O Brasil não tem mais horário de verão desde 2019, então -03:00 é fixo.
function brt(iso) {
  const d = new Date(iso);
  if (isNaN(d.getTime())) return null;
  const b = new Date(d.getTime() - 3 * 3600 * 1000);
  const p = (n) => String(n).padStart(2, '0');
  return b.getUTCFullYear() + '-' + p(b.getUTCMonth() + 1) + '-' + p(b.getUTCDate()) +
         'T' + p(b.getUTCHours()) + ':' + p(b.getUTCMinutes()) + ':' + p(b.getUTCSeconds()) + '-03:00';
}
function soData(v) {
  if (!v) return null;
  const s = String(v);
  if (/^\d{4}-\d{2}-\d{2}$/.test(s)) return s;
  const b = brt(s);
  return b ? b.slice(0, 10) : null;
}

const fields = {};
const pulados = [];

// opcional = campo que talvez nem exista no Bitrix ainda; não vira alerta.
function set(alias, valor, opcional) {
  const campo = mapa[alias];
  if (!campo) { if (!opcional) pulados.push(alias + ' (alias não cadastrado)'); return; }
  if (valor === null || valor === undefined || valor === '') { if (!opcional) pulados.push(alias + ' (o QS não tem esse dado)'); return; }
  fields[campo] = valor;
}

set('email_cliente', body.client_email);
set('data_agendamento', soData(body.booking_date));
set('datahora_meet', brt(body.scheduled_at));
set('produto_reuniao', body.produto || null, true);
set('link_meet', body.meeting_link || null, true);
set('duracao_reuniao', body.duration_min || null, true);

for (const par of [['sdr_agendou', body.scheduled_by], ['resp_reuniao', body.meeting_owner]]) {
  const alias = par[0], nome = par[1];
  if (!mapa[alias]) { pulados.push(alias + ' (alias não cadastrado)'); continue; }
  const id = acharOpcao(alias, nome);
  if (id) fields[mapa[alias]] = id;
  else pulados.push(alias + ' (nome "' + (nome || '—') + '" não bate com nenhuma opção)');
}

if (cfg.STAGE_REUNIAO) fields.STAGE_ID = String(cfg.STAGE_REUNIAO);

if (!body.bitrix_id) throw new Error('payload sem bitrix_id');
if (!Object.keys(fields).length) throw new Error('nada para gravar — nenhum alias preenchido em bitrix_fields');

// Sem meeting_id não há linha pra marcar. Um uuid que não casa com nada deixa
// o PATCH seguinte rodar em zero linhas, sem precisar de um IF só pra isso.
const meetingId = body.meeting_id || '00000000-0000-0000-0000-000000000000';

const quando = brt(body.scheduled_at);
const legivel = quando ? quando.slice(8, 10) + '/' + quando.slice(5, 7) + ' às ' + quando.slice(11, 16) : 'data não informada';

return [{ json: {
  deal_id: Number(body.bitrix_id),
  meeting_id: meetingId,
  pulados,
  comentario: '📅 Reunião agendada pelo QS para ' + legivel +
    (body.meeting_owner ? ' com ' + body.meeting_owner : '') + '.' +
    (body.meeting_link ? '\nMeet: ' + body.meeting_link : '\n(sem link do Meet ainda)') +
    (body.scheduled_by ? '\nAgendada por: ' + body.scheduled_by : '') +
    (pulados.length ? '\n⚠️ Não preenchidos: ' + pulados.join('; ') : ''),
  payload: { id: Number(body.bitrix_id), fields }
} }];

// Bitrix manda POST form-urlencoded: event, data[FIELDS][ID], auth[application_token], ts.
// Dependendo da versão o n8n entrega achatado ("data[FIELDS][ID]") ou aninhado — cobrimos os dois.
const cfg = $('Config (atividade Bitrix)').first().json;
const raiz = $input.first().json;
const b = raiz.body ?? raiz;

const activityId =
  b['data[FIELDS][ID]'] ??
  b?.data?.FIELDS?.ID ??
  b?.FIELDS?.ID ??
  b?.activity_id ??
  b?.ID ??
  null;

// Segurança: o Bitrix assina todo evento com o application_token do webhook de
// saída. Sem isto, qualquer um que descobrisse a URL do n8n moveria negócio no CRM.
const token = b['auth[application_token]'] ?? b?.auth?.application_token ?? '';
const esperado = String(cfg.APP_TOKEN || '').trim();
if (!esperado || esperado.startsWith('TROQUE')) {
  throw new Error('APP_TOKEN não configurado — o fluxo está aberto. Preencha no Config (atividade Bitrix).');
}
if (token !== esperado) {
  throw new Error('application_token não confere — evento recusado.');
}

// Evento sem ID (ping/handshake do Bitrix): para aqui, sem sujar o log de erro.
if (!activityId) return [];

return [{ json: { activity_id: String(activityId), evento: String(b.event ?? '') } }];

// ONCRMACTIVITYUPDATE dispara em QUALQUER mexida na atividade (editar texto, adiar...).
// ONCRMACTIVITYADD dispara quando o SDR registra uma ligação JÁ como concluída.
// Aqui fica só o que interessa: atividade DE NEGÓCIO, concluída, feita por gente.
const cfg = $('Config (atividade Bitrix)').first().json;
const resp = $input.first().json;

if (resp && resp.error) {
  throw new Error('Bitrix recusou o crm.activity.get: ' + resp.error + ' — ' + (resp.error_description || ''));
}

const r = resp.result;
if (!r) return [];

const tipoDono = String(cfg.ENTIDADE).toLowerCase() === 'lead' ? '1' : '2';
if (String(r.OWNER_TYPE_ID) !== tipoDono) return [];   // atividade de contato/empresa: ignora

const concluida =
  String(r.COMPLETED).toUpperCase() === 'Y' ||
  r.COMPLETED === true ||
  String(r.STATUS) === '2';
if (!concluida) return [];

// Filtro opcional por tipo (1=reunião, 2=ligação, 3=tarefa, 4=e-mail). Vazio = qualquer um.
const tipos = String(cfg.SO_TIPOS || '').replace(/\s/g, '');
if (tipos && !tipos.split(',').includes(String(r.TYPE_ID))) return [];

// IMPORTANTE: bloqueia atividade criada por robô (canal aberto/WhatsApp, formulário,
// e-mail de marketing). Sem isto uma mensagem automática move o negócio sozinha.
const bloq = String(cfg.PROVIDERS_IGNORADOS || '').replace(/\s/g, '').split(',').filter(Boolean);
if (bloq.includes(String(r.PROVIDER_ID || ''))) return [];

// Opcional: só conta se o responsável pela atividade for um dos SDRs listados.
const sdrs = String(cfg.SO_RESPONSAVEIS || '').replace(/\s/g, '').split(',').filter(Boolean);
if (sdrs.length && !sdrs.includes(String(r.RESPONSIBLE_ID || ''))) return [];

return [{ json: {
  activity_id: String(r.ID),
  owner_id: String(r.OWNER_ID),
  assunto: r.SUBJECT || '',
  type_id: String(r.TYPE_ID || ''),
  provider_id: String(r.PROVIDER_ID || ''),
  responsavel: String(r.RESPONSIBLE_ID || '')
} }];

// AQUI mora o "primeira atividade": só move quem AINDA está em STAGE_DE.
// Concluir a 2ª, 3ª, 10ª atividade não faz nada, porque o negócio já saiu de lá.
const cfgAtv = $('Config (atividade Bitrix)').first().json;
const cfg = $('Config (atividade Bitrix)').first().json;
const resp = $input.first().json;

if (resp && resp.error) {
  throw new Error('Bitrix recusou o crm.' + cfgAtv.ENTIDADE + '.get: ' + resp.error + ' — ' + (resp.error_description || ''));
}

const r = resp.result;
if (!r) return [];

const ehLead = String(cfgAtv.ENTIDADE).toLowerCase() === 'lead';
const campo = ehLead ? 'STATUS_ID' : 'STAGE_ID';
const atual = String(r[campo] || '');

if (atual !== String(cfg.STAGE_DE)) return [];

const fields = {};
fields[campo] = String(cfg.STAGE_PARA);

const atv = $('So atividade concluida do funil').first().json;

return [{ json: {
  id: String(r.ID),
  fields,
  de: atual,
  para: String(cfg.STAGE_PARA),
  assunto: atv.assunto,
  activity_id: atv.activity_id,
  responsavel: atv.responsavel
} }];

// ---------------------------------------------------------------------------
// Porta de entrada única. Valida, normaliza e decide a ação.
// Tudo que chega do QS é tratado como suspeito: campo faltando aqui vira
// resposta clara em vez de erro do Google 3 nós adiante.
// ---------------------------------------------------------------------------

// Troque pelo ID da agenda dedicada (ex.: c_xxx@group.calendar.google.com).
// 'primary' joga tudo na agenda pessoal da conta da operação.
const CALENDAR_PADRAO = 'primary';

const b = $input.first().json.body || {};
const acao = String(b.acao || 'criar').toLowerCase().trim();
const erros = [];

if (!b.meeting_id) erros.push('meeting_id ausente');
if (!['criar', 'reagendar', 'cancelar'].includes(acao)) erros.push('acao invalida: ' + acao);

if (acao === 'criar' || acao === 'reagendar') {
  if (!b.inicio) erros.push('inicio ausente');
  if (!b.fim) erros.push('fim ausente');
  if (b.inicio && b.fim && new Date(b.fim) <= new Date(b.inicio)) {
    erros.push('fim menor ou igual ao inicio');
  }
}
if (acao === 'reagendar' || acao === 'cancelar') {
  if (!b.event_id) erros.push('event_id ausente');
}

// E-mail malformado faz o Google recusar o evento INTEIRO com 400. Melhor
// descartar o convidado ruim e avisar o QS do que perder a reunião.
const EMAIL = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const brutos = (Array.isArray(b.convidados) ? b.convidados : [])
  .map((e) => String(e || '').trim())
  .filter(Boolean);
const convidados = brutos.filter((e) => EMAIL.test(e));
const descartados = brutos.filter((e) => !EMAIL.test(e));

// ID de evento determinístico: reenvio do mesmo meeting_id devolve 409 em vez
// de criar uma segunda reunião. O Google só aceita base32hex (a-v e 0-9).
function idEvento(seed) {
  const alfa = 'abcdefghijklmnopqrstuv0123456789';
  const s = 'qs-' + String(seed);
  let out = '';
  for (let i = 0; i < s.length; i++) {
    const c = s.charCodeAt(i);
    out += alfa[c % 32] + alfa[(c >> 5) % 32];
  }
  return ('qs' + out).slice(0, 60);
}

return [{ json: {
  acao: erros.length ? 'invalida' : acao,
  erros,
  meeting_id: b.meeting_id ?? null,
  calendar_id: b.calendar_id || CALENDAR_PADRAO,
  event_id: b.event_id || null,
  event_id_previsto: b.meeting_id ? idEvento(b.meeting_id) : null,
  inicio: b.inicio || null,
  fim: b.fim || null,
  timezone: b.timezone || 'America/Sao_Paulo',
  titulo: b.titulo || 'Reuniao',
  descricao: b.descricao || '',
  convidados,
  convidados_descartados: descartados
} }];

// Corpo do evento do Google Calendar.
//
// conferenceData.createRequest é o que faz o Google GERAR a sala do Meet. Sem
// o parâmetro conferenceDataVersion=1 na URL (no próximo nó) o Google IGNORA
// este bloco em silêncio: o evento nasce certinho, só que sem Meet nenhum.
//
// id determinístico + requestId estável = reenvio devolve 409 e a MESMA sala,
// em vez de duplicar a reunião.
const d = $json;

return [{ json: { ...d, evento: {
  id: d.event_id_previsto,
  summary: d.titulo,
  description: d.descricao,
  start: { dateTime: d.inicio, timeZone: d.timezone },
  end:   { dateTime: d.fim,   timeZone: d.timezone },
  attendees: d.convidados.map((email) => ({ email })),
  conferenceData: {
    createRequest: {
      requestId: 'qs-' + String(d.meeting_id),
      conferenceSolutionKey: { type: 'hangoutsMeet' }
    }
  },
  reminders: {
    useDefault: false,
    overrides: [ { method: 'popup', minutes: 30 }, { method: 'email', minutes: 60 } ]
  }
} } }];

// Resposta única da ação criar. Serve tanto para insert novo quanto para o
// caminho do 409 (evento já existia), porque os dois devolvem um Event.
//
// Nunca damos throw: o webhook responde 200 com ok:false e uma mensagem que se
// entende. Throw viraria 500 com stack trace e o QS perderia o motivo.
const r = $input.first().json;
const d = $('Validar entrada1').first().json;
const status = r.statusCode;
const ev = r.body || {};

// O 409 veio do POST, não deste nó: quando passamos pelo "Buscar evento
// existente", o status que chega aqui é o do GET (200).
let veioDo409 = false;
try { veioDo409 = $('Ja existe (409)?1').first().json.statusCode === 409; } catch (e) { veioDo409 = false; }

function motivo(body, st) {
  if (typeof body === 'string') return body.slice(0, 300);
  const e = body && body.error;
  if (typeof e === 'string') return e.slice(0, 300);
  if (e && (e.message || e.status)) return e.message || e.status;
  return 'HTTP ' + st;
}

if (status >= 400) {
  return [{ json: { ok: false, acao: 'criar', meeting_id: d.meeting_id, codigo: status, erro: motivo(ev, status) } }];
}

// EVENTO QUE EXISTE MAS ESTÁ CANCELADO.
// O Google guarda o id de um evento apagado. Então: alguém apaga o evento na
// mão, o QS tenta criar de novo com o mesmo meeting_id, o POST toma 409 e o GET
// devolve 200 com status "cancelled" — e o hangoutLink da sala MORTA.
if (ev.status === 'cancelled') {
  return [{ json: {
    ok: false,
    acao: 'criar',
    meeting_id: d.meeting_id,
    codigo: 'evento_cancelado',
    erro: 'o evento deste agendamento foi apagado no Google; refaça o agendamento no QS'
  } }];
}

// hangoutLink é o link do Meet. Se vier vazio, quase sempre falta o
// conferenceDataVersion=1 ou a conta não tem permissão de criar conferência.
const pontos = (ev.conferenceData && ev.conferenceData.entryPoints) || [];
const meet = ev.hangoutLink
  || pontos.filter((p) => p.entryPointType === 'video').map((p) => p.uri)[0]
  || null;

return [{ json: {
  ok: true,
  acao: 'criar',
  meeting_id: d.meeting_id,
  calendar_id: d.calendar_id,
  event_id: ev.id || null,
  meet_link: meet,
  html_link: ev.htmlLink || null,
  sem_meet: !meet,
  duplicado: veioDo409 || undefined,
  convidados_descartados: d.convidados_descartados
} }];

// PATCH só com o que muda. Não reenviamos conferenceData: a sala do Meet é
// preservada, então o cliente que já tem o link continua com o link certo.
const d = $json;

return [{ json: { ...d, patch: {
  summary: d.titulo,
  start: { dateTime: d.inicio, timeZone: d.timezone },
  end:   { dateTime: d.fim,   timeZone: d.timezone }
} } }];

const r = $input.first().json;
const d = $('Validar entrada1').first().json;
const status = r.statusCode;
const ev = r.body || {};

function motivo(body, st) {
  if (typeof body === 'string') return body.slice(0, 300);
  const e = body && body.error;
  if (typeof e === 'string') return e.slice(0, 300);
  if (e && (e.message || e.status)) return e.message || e.status;
  return 'HTTP ' + st;
}

// 404/410 = o evento sumiu do Google (apagado na mão, por exemplo). Devolvemos
// código nao_encontrado para o QS reagir chamando acao=criar.
if (status === 404 || status === 410) {
  return [{ json: {
    ok: false,
    acao: 'reagendar',
    meeting_id: d.meeting_id,
    codigo: 'nao_encontrado',
    erro: 'evento não existe mais no Google; recrie com acao=criar'
  } }];
}

if (status >= 400) {
  return [{ json: { ok: false, acao: 'reagendar', meeting_id: d.meeting_id, codigo: status, erro: motivo(ev, status) } }];
}

const pontos = (ev.conferenceData && ev.conferenceData.entryPoints) || [];
const meet = ev.hangoutLink
  || pontos.filter((p) => p.entryPointType === 'video').map((p) => p.uri)[0]
  || null;

return [{ json: {
  ok: true,
  acao: 'reagendar',
  meeting_id: d.meeting_id,
  calendar_id: d.calendar_id,
  event_id: ev.id || d.event_id,
  meet_link: meet,
  html_link: ev.htmlLink || null,
  inicio: d.inicio,
  fim: d.fim
} }];

const r = $input.first().json;
const d = $('Validar entrada1').first().json;
const status = r.statusCode;

function motivo(body, st) {
  if (typeof body === 'string') return body.slice(0, 300);
  const e = body && body.error;
  if (typeof e === 'string') return e.slice(0, 300);
  if (e && (e.message || e.status)) return e.message || e.status;
  return 'HTTP ' + st;
}

// Cancelar é idempotente: sucesso, já apagado ou nunca existiu dão no mesmo.
const apagado = status === 204 || status === 200 || status === 404 || status === 410;

if (!apagado) {
  return [{ json: { ok: false, acao: 'cancelar', meeting_id: d.meeting_id, codigo: status, erro: motivo(r.body, status) } }];
}

return [{ json: {
  ok: true,
  acao: 'cancelar',
  meeting_id: d.meeting_id,
  event_id: d.event_id,
  ja_estava_apagado: status === 404 || status === 410 || undefined
} }];

// Payload inválido nunca chega no Google. Responde 200 com ok:false e a lista
// de erros, que é o suficiente para achar o problema sem abrir log.
